import math
from collections import defaultdict


def solve(rows):
    """Return per-event mean absolute log error for station holdout predictions.

    Rows are dictionaries of CSV string values. Station IDs are held out as a
    group within each event, so a row can only be predicted from other stations.
    """
    grouped = defaultdict(list)
    for row in rows:
        event = row.get("event", "")
        station = row.get("station", "")
        if station is None or not str(station).strip():
            continue
        try:
            distance = float(row.get("dist", ""))
            acceleration = float(row.get("accel", ""))
        except (TypeError, ValueError):
            continue
        if not (distance > 0 and acceleration > 0):
            continue
        if not (math.isfinite(distance) and math.isfinite(acceleration)):
            continue
        grouped[str(event)].append((str(station), math.log(distance), math.log(acceleration)))

    errors = defaultdict(list)
    for event, records in grouped.items():
        for station, log_distance, observed_log_accel in records:
            donors = [record for record in records if record[0] != station]
            if not donors:
                continue
            distances = [abs(record[1] - log_distance) for record in donors]
            minimum = min(distances)
            tied_log_accels = [
                donor[2]
                for donor, delta in zip(donors, distances)
                if abs(delta - minimum) <= 1e-12
            ]
            prediction = sum(tied_log_accels) / len(tied_log_accels)
            errors[event].append(abs(observed_log_accel - prediction))

    return {
        event: sum(event_errors) / len(event_errors)
        for event, event_errors in errors.items()
        if event_errors
    }

