def solve(rows):
    """Return per-event mean absolute log error for station holdout predictions.

    Rows are dictionaries of CSV string values. Station IDs are held out as a
    group within each event, so a row can only be predicted from other stations.
    """
    grouped = defaultdict(list)
    for row in rows:
        event = row.get("event", "")
        station = row.get("station", "")
        if event is None or station is None:
            continue
        event = str(event).strip()
        station = str(station).strip()
        if not event or not station:
            continue
        try:
            distance = float(row.get("dist", ""))
            acceleration = float(row.get("accel", ""))
        except (TypeError, ValueError):
            continue
        if not (distance > 0 and acceleration > 0):
            continue
        if not (math.isfinite(distance) and math.isfinite(acceleration)):
            continue
        grouped[event].append((station, math.log(distance), math.log(acceleration)))

    errors = defaultdict(list)
    for event, records in grouped.items():
        for station, log_distance, observed_log_accel in records:
            donors = [record for record in records if record[0] != station]
            if not donors:
                continue
            distances = [abs(record[1] - log_distance) for record in donors]
            minimum = min(distances)
            tied_log_accels = [
                donor[2]
                for donor, delta in zip(donors, distances)
                if abs(delta - minimum) <= 1e-12
            ]
            prediction = sum(tied_log_accels) / len(tied_log_accels)
            errors[event].append(abs(observed_log_accel - prediction))

    return {
        event: sum(event_errors) / len(event_errors)
        for event, event_errors in errors.items()
        if event_errors
    }

import math
from collections import defaultdict

def solve(rows):
    ev = defaultdict(list)
    for r in rows:
        s = (r.get("station") or "").strip()
        if s == "" or s.upper() in ("NA", "NAN", "NULL", "NONE"):
            continue
        try:
            d = float(r["dist"]); a = float(r["accel"])
        except (ValueError, TypeError, KeyError):
            continue
        if not (d > 0 and a > 0 and math.isfinite(d) and math.isfinite(a)):
            continue
        ev[str(r["event"]).strip()].append((s, math.log(d), math.log(a)))
    out = {}
    for e, recs in ev.items():
        errs = []
        for s, ld, la in recs:
            donors = [(abs(ld2 - ld), la2) for s2, ld2, la2 in recs if s2 != s]
            if not donors:
                continue
            m = min(x[0] for x in donors)
            t = [la2 for dd, la2 in donors if dd <= m + 1e-12]
            errs.append(abs(sum(t) / len(t) - la))
        if errs:
            out[e] = sum(errs) / len(errs)
    return out

