"""Ordinal tobacco exposure discrimination by age."""


def solve(rows):
    """Return the case-control concordance score for each eligible age group."""
    categories = {name: index for index, name in enumerate(
        ("0-9g/day", "10-19", "20-29", "30+")
    )}
    groups = {}
    for row in rows:
        cases, controls = groups.setdefault(row["agegp"], ([0] * 4, [0] * 4))
        index = categories[row["tobgp"]]
        cases[index] += int(row["ncases"])
        controls[index] += int(row["ncontrols"])

    result = {}
    for age, (cases, controls) in groups.items():
        total_cases, total_controls = sum(cases), sum(controls)
        if not total_cases or not total_controls:
            continue
        lower_controls = 0
        twice_score = 0
        for case_count, control_count in zip(cases, controls):
            twice_score += case_count * (2 * lower_controls + control_count)
            lower_controls += control_count
        result[age] = twice_score / (2 * total_cases * total_controls)
    return result

