from collections import defaultdict


def solve(rows):
    trees = defaultdict(list)
    for row in rows:
        trees[row["Seed"]].append((float(row["age"]), float(row["height"])))

    result = {}
    for seed, observations in trees.items():
        if len(observations) < 3:
            continue
        observations.sort()
        errors = []
        for left, middle, right in zip(observations, observations[1:], observations[2:]):
            age, height = middle
            predicted = left[1] + (right[1] - left[1]) * (age - left[0]) / (right[0] - left[0])
            errors.append(abs(height - predicted))
        result[seed] = max(errors)
    return result

