from collections import defaultdict
from statistics import median


def solve(rows):
    """Return the first cumulative upward-drift alarm for each experiment."""
    grouped = defaultdict(dict)
    for row in rows:
        experiment = row["Expt"]
        run = int(row["Run"])
        speed = float(row["Speed"])
        grouped[experiment][run] = speed

    alarms = {}
    for experiment, runs in grouped.items():
        if not all(run in runs for run in (1, 2, 3)):
            continue
        baseline = median(runs[run] for run in (1, 2, 3))
        score = 0.0
        previous_run = 3
        for run in sorted(r for r in runs if r >= 4):
            if run != previous_run + 1:
                score = 0.0
            score = max(0.0, score + runs[run] - baseline - 10)
            if score >= 75:
                alarms[experiment] = run
                break
            previous_run = run
    return alarms

