from collections import defaultdict
from statistics import median

def solve(rows):
    """Return median local-contrast by treatment.

    Each row is a mapping with string values for rowpos, colpos, decrease,
    and treatment. Cells without measured orthogonal neighbors are omitted.
    """
    cells = {}
    for item in rows:
        r = int(item["rowpos"])
        c = int(item["colpos"])
        cells[(r, c)] = (float(item["decrease"]), item["treatment"])

    by_treatment = defaultdict(list)
    for (r, c), (value, treatment) in cells.items():
        neighbors = [cells[pos][0] for pos in
                     ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1))
                     if pos in cells]
        if neighbors:
            by_treatment[treatment].append(value - sum(neighbors) / len(neighbors))

    return {treatment: median(contrasts)
            for treatment, contrasts in sorted(by_treatment.items())}

