from collections import defaultdict
from statistics import median


def solve(rows):
    """Return median local contrasts keyed by represented treatment.

    Each input row must contain string values for ``rowpos``, ``colpos``,
    ``decrease``, and ``treatment``. A cell's contrast is its decrease minus
    the mean decrease of its measured orthogonal neighbors. Cells with no
    measured orthogonal neighbors contribute no contrast.
    """
    cells = {}
    for row in rows:
        position = (int(row["rowpos"]), int(row["colpos"]))
        cells[position] = (float(row["decrease"]), row["treatment"])

    contrasts_by_treatment = defaultdict(list)
    for (row, col), (decrease, treatment) in cells.items():
        neighbor_values = [
            cells[position][0]
            for position in (
                (row - 1, col),
                (row + 1, col),
                (row, col - 1),
                (row, col + 1),
            )
            if position in cells
        ]
        if neighbor_values:
            local_mean = sum(neighbor_values) / len(neighbor_values)
            contrasts_by_treatment[treatment].append(decrease - local_mean)

    return {
        treatment: median(contrasts_by_treatment[treatment])
        for treatment in sorted(contrasts_by_treatment)
    }

