def solve(rows):
    subs = {}
    for r in rows:
        subs.setdefault(r["Subject"], []).append((float(r["Time"]), float(r["conc"])))
    out = {}
    for s, pts in subs.items():
        pts.sort()
        m = max(c for _, c in pts)
        i = next(k for k, p in enumerate(pts) if p[1] == m)
        h = m / 2
        for k in range(i, len(pts) - 1):
            t0, c0 = pts[k]; t1, c1 = pts[k + 1]
            if c0 > h and c1 <= h:
                out[s] = t0 + (c0 - h) * (t1 - t0) / (c0 - c1)
                break
