from collections import defaultdict


def solve(rows):
    subjects = defaultdict(list)
    for row in rows:
        subjects[row["Subject"]].append((float(row["Time"]), float(row["conc"])))

    result = {}
    for subject, samples in subjects.items():
        samples.sort(key=lambda sample: sample[0])
        peak_index = max(range(len(samples)), key=lambda index: samples[index][1])
        half = samples[peak_index][1] / 2.0
        for (t0, c0), (t1, c1) in zip(samples[peak_index:], samples[peak_index + 1:]):
            if c0 > half and c1 <= half:
                result[subject] = t0 + (t1 - t0) * (c0 - half) / (c0 - c1)
                break
    return result

