def solve(rows):
    cells = {}
    for r in rows:
        cells.setdefault(r["wool"] + "/" + r["tension"], []).append(float(r["breaks"]))
    out = {}
    for k, v in cells.items():
        v.sort(reverse=True)
        need = len(v) / 4.0
        left = need
        tot = 0.0
        for x in v:
            t = min(1.0, left)
            tot += t * x
            left -= t
            if left <= 1e-12:
                break
        out[k] = tot / need
    return out

from collections import defaultdict


def solve(rows):
    cells = defaultdict(list)
    for row in rows:
        cells[f"{row['wool']}/{row['tension']}"].append(int(row['breaks']))

    result = {}
    for key, counts in cells.items():
        counts.sort(reverse=True)
        whole, remainder = divmod(len(counts), 4)
        weighted_sum = 4 * sum(counts[:whole])
        if remainder:
            weighted_sum += remainder * counts[whole]
        result[key] = weighted_sum / len(counts)
    return result

